  const style=document.createElement('style');
  style.textContent=`.site-logo{display:flex;align-items:center;width:150px;flex:0 0 150px}.site-logo img{display:block;width:145px;height:auto}header{gap:22px}header nav{gap:16px;margin-left:0;justify-content:center;align-items:center}header nav a{font-size:13px;white-space:nowrap}.search-panel{background:#101d35;padding:22px;display:grid;grid-template-columns:1fr auto;gap:12px;align-items:center;margin:0 0 26px}.search-panel label{color:#fff;font-weight:800;font-size:14px}.search-panel form{display:flex;gap:10px}.search-panel input{min-width:330px;border:0;padding:13px 14px;font:16px Arial,sans-serif}.search-panel button{border:0;background:#ff9a10;color:#111c30;padding:13px 17px;font-weight:850;font-size:14px;cursor:pointer}.catalog-wrap{padding:0 0 70px}.catalog-title{font:42px/1 Georgia,serif;letter-spacing:-.05em;margin:0 0 22px;max-width:600px}.catalog{display:grid;grid-template-columns:repeat(5,1fr);gap:15px}.catalog-card{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:156px;padding:20px 14px;text-align:center;background:#fff;border:1px solid #e6e5e3;border-radius:13px;color:#101d35;text-decoration:none;transition:transform .18s ease,background .18s ease,border-color .18s ease,box-shadow .18s ease}.catalog-card:hover,.catalog-card:focus-visible{background:#39b8da;border-color:#1688c9;box-shadow:0 13px 25px rgba(33,100,166,.18);transform:translateY(-4px);outline:0}.catalog-icon{display:grid;place-items:center;width:49px;height:49px;border-radius:12px;background:#2fa7d4;color:#075bcc;font:850 12px Arial,sans-serif;letter-spacing:.08em}.catalog-card:hover .catalog-icon,.catalog-card:focus-visible .catalog-icon{background:#0f86d3;color:#063fa3}.catalog-card strong{margin-top:11px;font-size:15px;line-height:1.2}.catalog-card small{display:block;min-height:30px;margin-top:7px;color:#65707b;font-size:12px;line-height:1.25}.catalog-card:hover small,.catalog-card:focus-visible small{color:#0c4a7d}.card-markers{display:flex;gap:4px;margin-top:9px}.card-markers i{width:6px;height:6px;border-radius:50%;background:#4968f6}.sr-only{position:absolute;width:1px;height:1px;margin:-1px;clip:rect(0,0,0,0);overflow:hidden;white-space:nowrap}.article{max-width:840px;padding:48px 0 84px}.article h2{font:36px/1.06 Georgia,serif;letter-spacing:-.05em;margin:40px 0 12px}.article p{color:#40506a;font-size:17px}.article .meta{color:#2857d6;font-size:12px;font-weight:850;letter-spacing:.1em;text-transform:uppercase}.detail-grid{display:grid;grid-template-columns:1.08fr .92fr;gap:18px;padding:38px 0 76px}.category-copy,.category-action{min-height:360px;padding:36px;background:#fff}.category-copy h2,.category-action h2{font:clamp(34px,4vw,55px)/.95 Georgia,serif;letter-spacing:-.06em;margin:11px 0 18px}.category-copy p{max-width:530px;color:#40506a;font-size:17px}.category-action{display:flex;flex-direction:column;justify-content:space-between;background:#101d35;color:#fff}.category-action p{color:#d6deed;font-size:16px}.category-action .btn{align-self:flex-start;background:#ff9a10;border-color:#ff9a10;color:#101d35}.back-link{color:#2857d6;font-size:14px;font-weight:800;text-decoration:none}.dossier{display:grid;grid-template-columns:1.02fr .98fr;gap:18px;padding:38px 0 76px}.dossier-main{position:relative;min-height:455px;padding:38px;background:#2857d6;color:#fff;overflow:hidden}.dossier-main:after{content:'';position:absolute;width:300px;height:300px;right:-94px;bottom:-102px;border:30px solid #ff9a10;border-radius:50%;opacity:.95}.dossier-main h2{position:relative;z-index:1;max-width:480px;font:clamp(43px,5vw,70px)/.9 Georgia,serif;letter-spacing:-.07em;margin:20px 0}.dossier-main p{position:relative;z-index:1;max-width:430px;color:#e9efff;font-size:17px}.dossier-code{position:relative;z-index:1;display:inline-flex;gap:8px;margin-top:28px;padding:10px 12px;border:1px solid rgba(255,255,255,.42);font:800 11px Arial,sans-serif;letter-spacing:.12em}.dossier-side{display:grid;grid-template-rows:1fr auto;gap:18px}.signal-card{padding:31px;background:#fff}.signal-card h3{font:34px/.98 Georgia,serif;letter-spacing:-.05em;margin:10px 0 16px}.signal-list{display:grid;gap:9px;margin:20px 0 0;padding:0;list-style:none}.signal-list li{padding:10px 0;border-top:1px solid #d8d3ca;font-size:14px;font-weight:750}.signal-list li:first-child{border-top:0}.dossier-action{padding:27px;background:#ff9a10;color:#101d35}.dossier-action p{margin:0 0 17px;font-size:16px;font-weight:750}.dossier-action .btn{background:#101d35;color:#fff;border-color:#101d35}.detail-grid article{background:#fff;padding:28px}.detail-grid h2{font:30px/1.06 Georgia,serif;margin:7px 0 12px}@media(max-width:980px){header{flex-wrap:wrap;padding-top:18px;padding-bottom:18px}.site-logo{width:145px}header nav{order:3;width:100%;justify-content:space-between;overflow-x:auto;padding-bottom:2px}.catalog{grid-template-columns:repeat(3,1fr)}}@media(max-width:780px){.search-panel{grid-template-columns:1fr}.search-panel form{display:grid;grid-template-columns:1fr}.search-panel input{width:100%;min-width:0}.catalog{grid-template-columns:repeat(2,1fr);gap:10px}.catalog-card{min-height:145px}.detail-grid,.dossier{grid-template-columns:1fr}.category-copy,.category-action{min-height:0;padding:28px}.catalog-title{font-size:35px}}`;
